(339909, 26223, 5728, '<td valign="top">Looks like this is a jungle somewhere. Good depiction of the challenge, the leading lines work well. Maybe a little boost on the contrast - 9.</td>', 'Looks like this is a jungle somewhere. Good depiction of the challenge, the leading lines work well. Maybe a little boost on the contrast - 9.', '2003-06-27 05:54:27.000000', NULL, 1),
(339910, 25910, 8643, '<td valign="top">The skyline is oversharpened for my taste</td>', 'The skyline is oversharpened for my taste', '2003-06-27 05:55:05.000000', NULL, 1),
