(339912, 26204, 9669, '<td valign="top">nice, but probably has more meaning for the owner, that we could not possibly understand</td>', 'nice, but probably has more meaning for the owner, that we could not possibly understand', '2003-06-27 05:56:25.000000', NULL, 1),
(339913, 26198, 9669, '<td valign="top">would be just as nice without the border</td>', 'would be just as nice without the border', '2003-06-27 05:57:32.000000', NULL, 1),
